CREATE TABLE IF NOT EXISTS `accounts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `type` TEXT NOT NULL, `groupName` TEXT NOT NULL, `institution` TEXT NOT NULL, `initialBalance` INTEGER NOT NULL, `currency` TEXT NOT NULL, `includeInNetWorth` INTEGER NOT NULL, `note` TEXT NOT NULL, `isHidden` INTEGER NOT NULL, `isArchived` INTEGER NOT NULL, `sortOrder` INTEGER NOT NULL, `creditLimit` INTEGER NOT NULL, `statementDay` INTEGER NOT NULL, `paymentDueDay` INTEGER NOT NULL, `linkedBankAccountId` INTEGER, `interestRate` REAL NOT NULL, `lenderName` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `categories` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `type` TEXT NOT NULL, `iconName` TEXT NOT NULL, `colorHex` TEXT NOT NULL, `parentId` INTEGER, `sortOrder` INTEGER NOT NULL, `isHidden` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `transactions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `type` TEXT NOT NULL, `dateMillis` INTEGER NOT NULL, `amount` INTEGER NOT NULL, `accountId` INTEGER NOT NULL, `toAccountId` INTEGER, `transferFee` INTEGER NOT NULL, `categoryId` INTEGER NOT NULL, `subcategoryId` INTEGER, `payee` TEXT NOT NULL, `note` TEXT NOT NULL, `tags` TEXT NOT NULL, `receiptUri` TEXT, `paymentMethod` TEXT NOT NULL, `isExcludedFromStats` INTEGER NOT NULL, `recurringRuleId` INTEGER, `installmentId` INTEGER, `isBookmarked` INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS `index_transactions_accountId` ON `transactions` (`accountId`);
CREATE INDEX IF NOT EXISTS `index_transactions_toAccountId` ON `transactions` (`toAccountId`);
CREATE INDEX IF NOT EXISTS `index_transactions_categoryId` ON `transactions` (`categoryId`);
CREATE INDEX IF NOT EXISTS `index_transactions_dateMillis` ON `transactions` (`dateMillis`);
CREATE TABLE IF NOT EXISTS `budgets` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `categoryId` INTEGER NOT NULL, `monthString` TEXT NOT NULL, `amount` INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `index_budgets_categoryId_monthString` ON `budgets` (`categoryId`, `monthString`);
CREATE TABLE IF NOT EXISTS `recurring_transactions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `type` TEXT NOT NULL, `amount` INTEGER NOT NULL, `accountId` INTEGER NOT NULL, `toAccountId` INTEGER, `categoryId` INTEGER NOT NULL, `subcategoryId` INTEGER, `payee` TEXT NOT NULL, `note` TEXT NOT NULL, `frequency` TEXT NOT NULL, `startDateMillis` INTEGER NOT NULL, `endDateMillis` INTEGER, `nextDueDateMillis` INTEGER NOT NULL, `lastProcessedDateMillis` INTEGER, `isActive` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `installment_plans` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `totalAmount` INTEGER NOT NULL, `totalInstallments` INTEGER NOT NULL, `paidInstallments` INTEGER NOT NULL, `monthlyAmount` INTEGER NOT NULL, `accountId` INTEGER NOT NULL, `categoryId` INTEGER NOT NULL, `payee` TEXT NOT NULL, `note` TEXT NOT NULL, `startDateMillis` INTEGER NOT NULL, `nextDueDateMillis` INTEGER NOT NULL, `isCompleted` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `daily_memos` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `dateString` TEXT NOT NULL, `memoText` TEXT NOT NULL, `colorHex` TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `index_daily_memos_dateString` ON `daily_memos` (`dateString`);
CREATE TABLE IF NOT EXISTS `bookmarks` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `type` TEXT NOT NULL, `amount` INTEGER NOT NULL, `accountId` INTEGER NOT NULL, `toAccountId` INTEGER, `categoryId` INTEGER NOT NULL, `subcategoryId` INTEGER, `payee` TEXT NOT NULL, `note` TEXT NOT NULL, `paymentMethod` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `app_settings` (`key` TEXT NOT NULL, `value` TEXT NOT NULL, PRIMARY KEY(`key`));
